from model import Job, Summary


def run(jobs, budget):
    by_id = {job.id: job for job in jobs}
    unfinished = set(by_id)
    completed = set()
    order = []
    spent = 0

    while True:
        remaining = budget - spent
        chosen = None
        for job_id in sorted(unfinished):
            job = by_id[job_id]
            if job.cost <= remaining and all(dep in completed for dep in job.deps):
                chosen = job
                break
        if chosen is None:
            break
        unfinished.remove(chosen.id)
        completed.add(chosen.id)
        order.append(chosen.id)
        spent += chosen.cost

    return Summary(order, spent, len(unfinished))

